package orm_relation

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

// The ported ofMany fixtures are declared the way Laravel's tests declare them - the array form with
// lowercase aggregates, the closure, a structured join - so each relation renders Laravel's own
// statement. Nothing else asserted these fixtures' SQL, which let an OfMany(col, "MAX") declaration and
// a raw join string drift from Laravel unnoticed. Every expectation is Laravel's toSql() for the
// same relation (oracle, illuminate/database v12.55.1, sqlite,
// /Users/dog/.claude/jobs/013c27a0/tmp/ofm/fixture_sql_probe.php -> fixture_sql_probe.out).

func TestHasOneOfMany_ClosureFixturesRenderLaravelSQL(t *testing.T) {
	query := newRelationQuery(t)
	for _, tt := range []struct{ relation, sql string }{
		{"LatestLoginWithFooState", `select "logins".* from "logins" inner join (select max("logins"."id") as "id_aggregate", "logins"."user_id" from "logins" inner join "states" on "states"."user_id" = "logins"."user_id" where "states"."type" = ? and "logins"."user_id" = ? and "logins"."user_id" is not null group by "logins"."user_id") as "latest_login_with_foo_state" on "latest_login_with_foo_state"."id_aggregate" = "logins"."id" and "latest_login_with_foo_state"."user_id" = "logins"."user_id" where "logins"."user_id" = ? and "logins"."user_id" is not null`},
		{"FooState", `select "states".* from "states" inner join (select MAX("states"."id") as "id_aggregate", "states"."user_id" from "states" where "type" = ? and "states"."user_id" = ? and "states"."user_id" is not null group by "states"."user_id") as "foo_state" on "foo_state"."id_aggregate" = "states"."id" and "foo_state"."user_id" = "states"."user_id" where "states"."user_id" = ? and "states"."user_id" is not null`},
		{"LastUpdatedFooState", `select "states".* from "states" inner join (select max("states"."id") as "id_aggregate", min("states"."updated_at") as "updated_at_aggregate", "states"."user_id" from "states" inner join (select max("states"."updated_at") as "updated_at_aggregate", "states"."user_id" from "states" where "type" = ? and "states"."user_id" = ? and "states"."user_id" is not null group by "states"."user_id") as "last_updated_foo_state" on "last_updated_foo_state"."updated_at_aggregate" = "states"."updated_at" and "last_updated_foo_state"."user_id" = "states"."user_id" where "type" = ? group by "states"."user_id") as "last_updated_foo_state" on "last_updated_foo_state"."id_aggregate" = "states"."id" and "last_updated_foo_state"."updated_at_aggregate" = "states"."updated_at" and "last_updated_foo_state"."user_id" = "states"."user_id" where "states"."user_id" = ? and "states"."user_id" is not null`},
		{"Price", `select "prices".* from "prices" inner join (select max("prices"."id") as "id_aggregate", min("prices"."published_at") as "published_at_aggregate", "prices"."user_id" from "prices" inner join (select max("prices"."published_at") as "published_at_aggregate", "prices"."user_id" from "prices" where "published_at" < ? and "prices"."user_id" = ? and "prices"."user_id" is not null group by "prices"."user_id") as "price" on "price"."published_at_aggregate" = "prices"."published_at" and "price"."user_id" = "prices"."user_id" where "published_at" < ? group by "prices"."user_id") as "price" on "price"."id_aggregate" = "prices"."id" and "price"."published_at_aggregate" = "prices"."published_at" and "price"."user_id" = "prices"."user_id" where "prices"."user_id" = ? and "prices"."user_id" is not null`},
		{"PriceWithoutKeyInAggregates", `select "prices".* from "prices" inner join (select MAX("prices"."id") as "id_aggregate", min("prices"."published_at") as "published_at_aggregate", "prices"."user_id" from "prices" inner join (select MAX("prices"."published_at") as "published_at_aggregate", "prices"."user_id" from "prices" where "prices"."user_id" = ? and "prices"."user_id" is not null group by "prices"."user_id") as "price_without_key_in_aggregates" on "price_without_key_in_aggregates"."published_at_aggregate" = "prices"."published_at" and "price_without_key_in_aggregates"."user_id" = "prices"."user_id" group by "prices"."user_id") as "price_without_key_in_aggregates" on "price_without_key_in_aggregates"."id_aggregate" = "prices"."id" and "price_without_key_in_aggregates"."published_at_aggregate" = "prices"."published_at" and "price_without_key_in_aggregates"."user_id" = "prices"."user_id" where "prices"."user_id" = ? and "prices"."user_id" is not null`},
		{"PriceWithoutGlobalScope", `select "prices".* from "prices" inner join (select max("prices"."id") as "id_aggregate", min("prices"."published_at") as "published_at_aggregate", "prices"."user_id" from "prices" inner join (select max("prices"."published_at") as "published_at_aggregate", "prices"."user_id" from "prices" where "published_at" < ? and "prices"."user_id" = ? and "prices"."user_id" is not null group by "prices"."user_id") as "price_without_global_scope" on "price_without_global_scope"."published_at_aggregate" = "prices"."published_at" and "price_without_global_scope"."user_id" = "prices"."user_id" where "published_at" < ? group by "prices"."user_id") as "price_without_global_scope" on "price_without_global_scope"."id_aggregate" = "prices"."id" and "price_without_global_scope"."published_at_aggregate" = "prices"."published_at" and "price_without_global_scope"."user_id" = "prices"."user_id" where "prices"."user_id" = ? and "prices"."user_id" is not null`},
	} {
		t.Run(tt.relation, func(t *testing.T) {
			user := hasOneOfManyUser{ID: 1}
			assert.Equal(t, tt.sql, cloneRelationQuery(t, query).Related(&user, tt.relation).ToSql().Get(&[]hasOneOfManyLogin{}))
		})
	}
}

